// static
bool StructTraits<::crosapi::mojom::SnapshotSource::DataView, ::crosapi::mojom::SnapshotSourcePtr>::Read(
    ::crosapi::mojom::SnapshotSource::DataView input,
    ::crosapi::mojom::SnapshotSourcePtr* output) {
  bool success = true;
  ::crosapi::mojom::SnapshotSourcePtr result(::crosapi::mojom::SnapshotSource::New());
  
      if (success)
        result->id = input.id();
      if (success && !input.ReadTitle(&result->title))
        success = false;
      if (success && !input.ReadWindowUniqueId(&result->window_unique_id))
        success = false;
      if (success)
        result->display_id = input.display_id();
  *output = std::move(result);
  return success;
}

